1	// Drive the dashboard in a real browser against a fake GitHub, and screenshot it.
2	//
3	//   node drive.mjs [--url http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:8099/packs/claudinite-dashboard/] [--out shot.png]
4	//                  [--repo owner/name] [--wait 3000]
5	//
6	// The page is left untouched: `fetch` is stubbed in the page context before any module
7	// runs, so what renders is the real client against a synthetic fleet.
8	
9	import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';
10	
11	const arg = (name, fallback) => {
12	  const i = process.argv.indexOf(`--${name}`);
13	  return i === -1 ? fallback : process.argv[i + 1];
14	};
15	
16	const url = arg('url', 'http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:8099/packs/claudinite-dashboard/');
17	const out = arg('out', '/tmp/shot.png');
18	const wait = Number(arg('wait', 3500));
19	
20	const browser = await chromium.launch({ executablePath: '/opt/pw-browsers/chromium-1194/chrome-linux/chrome' });
21	const page = await browser.newPage({ viewport: { width: 1280, height: 1400 } });
22	
23	page.on('console', (m) => process.stdout.write(`[console.${m.type()}] ${m.text()}\n`));
24	page.on('pageerror', (e) => process.stdout.write(`[pageerror] ${e.message}\n`));
25	
26	await page.addInitScript(() => {
27	  const DAY = 86400e3;
28	  const now = Date.now();
29	  const iso = (d) => new Date(now - d * DAY).toISOString();
30	  const day = (d) => new Date(now - d * DAY).toISOString().slice(0, 10);
31	
32	  const members = ['acme/alpha', 'acme/bravo', 'acme/charlie', 'acme/delta', 'acme/echo'];
33	
34	  const item = (n, repo, task, over = {}) => ({
35	    number: n,
36	    title: `[claudinite-work] ${task}`,
37	    body: 'packs/basics/tasks/x/task.md\n',
38	    state: 'closed',
39	    labels: [{ name: 'outcome:done' }],
40	    created_at: iso(3),
41	    updated_at: iso(1),
42	    closed_at: iso(1),
43	    comments: 1,
44	    ...over,
45	  });
46	
47	  const issuesFor = (repo) => {
48	    const i = members.indexOf(repo);
49	    const out = [];
50	    for (let d = 0; d < 12; d += 1) {
51	      const many = (i + d) % 3;
52	      for (let k = 0; k <= many; k += 1) {
53	        out.push(item(100 + d * 10 + k, repo, `core/task-${k}`, {
54	          closed_at: iso(d), updated_at: iso(d), created_at: iso(d + 1),
55	          labels: [{ name: ['outcome:done', 'outcome:delivered', 'outcome:obsolete'][(d + k) % 3] }],
56	        }));
57	      }
58	    }
59	    out.push(item(9, repo, 'core/parked', { state: 'open', labels: [{ name: 'needs-human' }], closed_at: null, updated_at: iso(4) }));
60	    if (i % 2) out.push(item(8, repo, 'core/ready', { state: 'open', labels: [{ name: 'ready' }], closed_at: null, updated_at: iso(0) }));
61	    out.push({ ...item(7, repo, 'x'), title: 'a plain issue', labels: [] });
62	    out.push({ ...item(6, repo, 'x'), title: 'a pull request', pull_request: { url: 'x' }, state: 'open', closed_at: null, draft: false, user: { login: 'someone' } });
63	    return out;
64	  };
65	
66	  const runsFor = (repo) => {
67	    const i = members.indexOf(repo);
68	    const out = [];
69	    for (let d = 0; d < 10; d += 1) {
70	      out.push({
71	        name: 'Claudinite scheduler', status: 'completed',
72	        conclusion: (d === 2 && i === 1) ? 'failure' : 'success',
73	        event: 'schedule', head_branch: 'main', created_at: iso(d),
74	        html_url: 'https://example.invalid/run',
75	      });
76	    }
77	    return { workflow_runs: out };
78	  };
79	
80	  const declaration = (repo) => JSON.stringify({
81	    packs: ['core', 'basics', 'tidy-repo', 'claudinite-dashboard'],
82	    taskScheduler: { dailyHour: 4 },
83	    claudinite: { ref: repo === 'acme/echo' ? 'oldsha0' : 'canonsha', engineVersion: 4, updated: iso(repo === 'acme/echo' ? 12 : 0) },
84	  });
85	
86	  const digest = (d) => `Fleet operations — ${day(d)}\n\nYesterday's biggest work:\n\n`
87	    + `• alpha — #289 Ticket refresh now recovers from partial API failures. https://github.com/acme/alpha/pull/289\n\n`
88	    + `• bravo — #147 New release pipeline; version bumps are one command. https://github.com/acme/bravo/pull/147\n\n`
89	    + `Worth returning to:\n\n• acme/delta — last meaningful change ${day(21)}: #157 Store release automation. https://github.com/acme/delta/pull/157\n\n`
90	    + `Three weeks quiet. The store release landed but nothing has used it since — worth a look.\n`;
91	
92	  const json = (body) => new Response(JSON.stringify(body), {
93	    status: 200,
94	    headers: { 'content-type': 'application/json', 'x-ratelimit-remaining': '4900', 'x-ratelimit-limit': '5000', 'x-ratelimit-reset': String(Math.floor(now / 1000) + 3000), etag: `W/"${Math.random()}"` },
95	  });
96	  const text = (body) => new Response(body, { status: 200, headers: { 'content-type': 'text/plain', 'x-ratelimit-remaining': '4900' } });
97	  const missing = () => new Response('Not Found', { status: 404, headers: { 'x-ratelimit-remaining': '4900' } });
98	
99	  const real = window.fetch;
100	  window.fetch = async (input, init) => {
101	    const u = String(input);
102	    if (u.includes('dashboard.config.json')) {
103	      return json({ canonRepo: 'acme/alpha', repos: members, digestsRepo: 'acme/enforcer' });
104	    }
105	    if (!u.includes('api.github.com')) return real(input, init);
106	
107	    const path = new URL(u).pathname;
108	    if (path === '/rate_limit') return json({ resources: { core: { remaining: 4900, limit: 5000, reset: Math.floor(now / 1000) + 3000 } } });
109	    if (path === '/user') return json({ login: 'viewer', avatar_url: '', html_url: '' });
110	
111	    const m = /^\/repos\/([^/]+\/[^/]+)(\/.*)?$/.exec(path);
112	    if (!m) return missing();
113	    const [, repo, rest = ''] = m;
114	    if (repo === 'acme/charlie' && rest.startsWith('/contents')) return missing();   // not adopted
115	    if (rest === '') return json({ default_branch: 'main', private: false, full_name: repo });
116	    if (rest.startsWith('/commits/')) return json({ sha: `sha${repo.length}`, commit: { committer: { date: iso(members.indexOf(repo) % 4) } } });
117	    if (rest.startsWith('/contents/digests/')) {
118	      const d = decodeURIComponent(rest).match(/(\d{4}-\d{2}-\d{2})/)?.[1];
119	      return d === day(2) ? missing() : text(digest(1));
120	    }
121	    if (rest.startsWith('/contents/')) return text(declaration(repo));
122	    if (rest.startsWith('/git/trees/')) {
123	      return json({ tree: ['core', 'basics'].flatMap((p) => [1, 2].map((n) => ({ type: 'blob', path: `packs/${p}/tasks/task-${n}/task.mjs` }))) });
124	    }
125	    if (rest.startsWith('/issues')) return json(issuesFor(repo));
126	    if (rest.startsWith('/actions/runs')) return json(runsFor(repo));
127	    return missing();
128	  };
129	});
130	
131	const target = arg('repo') ? `${url}?repo=${encodeURIComponent(arg('repo'))}` : url;
132	await page.goto(target, { waitUntil: 'load' });
133	await page.waitForTimeout(wait);
134	const dump = arg('dump');
135	if (dump) {
136	  const rows = await page.$$eval(dump, (ns) => ns.map((n) => n.innerText.replace(/\s*\n\s*/g, ' | ')));
137	  process.stdout.write(`${rows.join('\n')}\n`);
138	}
139	const sel = arg('el');
140	if (sel) await page.locator(sel).screenshot({ path: out });
141	else await page.screenshot({ path: out, fullPage: true });
142	process.stdout.write(`shot → ${out}\n`);
143	await browser.close();

1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import {
4	  activitySeries, fleetBenefits, dayLadder, dayKey, delta,
5	} from '../../packs/claudinite-dashboard/activity.mjs';
6	import {
7	  READY, NEEDS_HUMAN, OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE,
8	} from '../../engine/scheduler/queue/work-item.mjs';
9	
10	const NOW = Date.parse('2026-08-18T12:00:00Z');
11	const DAY = 86400e3;
12	
13	const closedWork = (closedAt, labels = [OUTCOME_DONE]) => ({
14	  number: 1,
15	  title: '[claudinite-work] basics/task-janitor',
16	  state: 'closed',
17	  labels,
18	  created_at: new Date(Date.parse(closedAt) - DAY).toISOString(),
19	  updated_at: closedAt,
20	  closed_at: closedAt,
21	});
22	
23	const read = (over = {}) => ({
24	  repo: 'o/a',
25	  declaration: { packs: ['core'], claudinite: { updated: '2026-08-18T02:00:00Z' } },
26	  items: [],
27	  itemsComplete: true,
28	  runs: [],
29	  head: { sha: 'abc', committedAt: null },
30	  ...over,
31	});
32	
33	test('the ladder is UTC days, oldest first, ending today', () => {
34	  const days = dayLadder(NOW, 3);
35	  assert.deepEqual(days, ['2026-08-16', '2026-08-17', '2026-08-18']);
36	  assert.equal(dayKey(NOW), '2026-08-18');
37	});
38	
39	test('closed work lands on its own day, stacked by outcome', () => {
40	  const s = activitySeries([read({
41	    items: [
42	      closedWork('2026-08-17T09:00:00Z', [OUTCOME_DONE]),
43	      closedWork('2026-08-17T22:00:00Z', [OUTCOME_DELIVERED]),
44	      closedWork('2026-08-18T01:00:00Z', [OUTCOME_OBSOLETE]),
45	      closedWork('2026-08-18T02:00:00Z', []),
46	    ],
47	  })], { now: NOW, days: 3 });
48	
49	  const byDay = Object.fromEntries(s.days.map((d) => [d.day, d]));
50	  assert.equal(byDay['2026-08-17'].work[OUTCOME_DONE], 1);
51	  assert.equal(byDay['2026-08-17'].work[OUTCOME_DELIVERED], 1);
52	  assert.equal(byDay['2026-08-18'].work[OUTCOME_OBSOLETE], 1);
53	  assert.equal(byDay['2026-08-18'].work.none, 1);
54	  assert.equal(byDay['2026-08-16'].workClosed, 0);
55	  assert.equal(s.totals.workClosed, 4);
56	});
57	
58	test('an issue that is not a work item is counted apart from the queue', () => {
59	  const s = activitySeries([read({
60	    items: [{ ...closedWork('2026-08-18T01:00:00Z'), title: 'a plain issue', labels: [] }],
61	  })], { now: NOW, days: 3 });
62	  assert.equal(s.totals.workClosed, 0);
63	  assert.equal(s.totals.otherClosed, 1);
64	});
65	
66	test('runs are bucketed by conclusion, and in-flight is neither pass nor fail', () => {
67	  const s = activitySeries([read({
68	    runs: [
69	      { created_at: '2026-08-18T01:00:00Z', status: 'completed', conclusion: 'success' },
70	      { created_at: '2026-08-18T02:00:00Z', status: 'completed', conclusion: 'failure' },
71	      { created_at: '2026-08-18T03:00:00Z', status: 'in_progress', conclusion: null },
72	    ],
73	  })], { now: NOW, days: 3 });
74	  const today = s.days.at(-1);
75	  assert.equal(today.runs.success, 1);
76	  assert.equal(today.runs.failure, 1);
77	  assert.equal(today.runs.other, 1);
78	  assert.equal(s.totals.runsFailed, 1);
79	});
80	
81	test('a member that did nothing is quiet, and one that could not be read is neither', () => {
82	  const s = activitySeries([
83	    read({ repo: 'o/busy', runs: [{ created_at: '2026-08-18T01:00:00Z', status: 'completed', conclusion: 'success' }] }),
84	    read({ repo: 'o/quiet' }),
85	    { repo: 'o/private', error: { status: 404 } },
86	  ], { now: NOW, days: 3 });
87	
88	  assert.deepEqual(s.moved, ['o/busy']);
89	  assert.deepEqual(s.quiet, ['o/quiet']);
90	  assert.equal(s.members, 2);
91	  assert.equal(s.unread, 1);
92	});
93	
94	test('a default-branch commit counts as movement even with nothing closed', () => {
95	  const s = activitySeries([read({ head: { sha: 'abc', committedAt: '2026-08-17T10:00:00Z' } })],
96	    { now: NOW, days: 3 });
97	  assert.deepEqual(s.moved, ['o/a']);
98	  assert.equal(s.days.find((d) => d.day === '2026-08-17').moved, 1);
99	});
100	
101	test('an incomplete issue page declares the day its counts become a floor', () => {
102	  const s = activitySeries([read({
103	    itemsComplete: false,
104	    items: [closedWork('2026-08-17T09:00:00Z')],
105	  })], { now: NOW, days: 5 });
106	  // The oldest issue the page could see is the closed item's creation, a day before it.
107	  assert.equal(s.horizon.issues, '2026-08-16');
108	});
109	
110	test('a complete issue page has no horizon — every day is a real count', () => {
111	  const s = activitySeries([read({ items: [closedWork('2026-08-17T09:00:00Z')] })], { now: NOW, days: 5 });
112	  assert.equal(s.horizon.issues, null);
113	});
114	
115	// --- benefits -------------------------------------------------------------------
116	
117	test('the benefit figures are windowed, and compared against the window before', () => {
118	  const b = fleetBenefits([read({
119	    items: [
120	      closedWork('2026-08-17T09:00:00Z', [OUTCOME_DONE]),
121	      closedWork('2026-08-16T09:00:00Z', [OUTCOME_DELIVERED]),
122	      closedWork('2026-08-08T09:00:00Z', [OUTCOME_DONE]),
123	      closedWork('2026-08-01T09:00:00Z', [OUTCOME_DONE]),     // before both windows
124	    ],
125	  })], { now: NOW, windowDays: 7 });
126	
127	  assert.equal(b.current.completed, 2);
128	  assert.equal(b.previous.completed, 1);
129	  assert.deepEqual(delta(b.current.completed, b.previous.completed), { dir: 'up', by: 1 });
130	});
131	
132	test('an item closed while parked is completed work a human was pulled into', () => {
133	  const b = fleetBenefits([read({
134	    items: [
135	      closedWork('2026-08-17T09:00:00Z', [OUTCOME_DONE]),
136	      closedWork('2026-08-17T10:00:00Z', [OUTCOME_DONE, NEEDS_HUMAN]),
137	    ],
138	  })], { now: NOW, windowDays: 7 });
139	
140	  assert.equal(b.current.completed, 2);
141	  assert.equal(b.current.unattended, 1);
142	  assert.equal(b.current.parked, 1);
143	});
144	
145	test('an item still sitting parked counts as one that needed a person', () => {
146	  const b = fleetBenefits([read({
147	    items: [{
148	      ...closedWork('2026-08-17T09:00:00Z', [NEEDS_HUMAN]),
149	      state: 'open',
150	      closed_at: null,
151	      updated_at: '2026-08-17T09:00:00Z',
152	    }],
153	  })], { now: NOW, windowDays: 7 });
154	  assert.equal(b.current.parked, 1);
155	  assert.equal(b.current.completed, 0);
156	});
157	
158	test('an outcome-less closure is not counted as completed work', () => {
159	  const b = fleetBenefits([read({ items: [closedWork('2026-08-17T09:00:00Z', [READY])] })],
160	    { now: NOW, windowDays: 7 });
161	  assert.equal(b.current.completed, 0);
162	});
163	
164	test('converging counts only the current window — a stamp carries one date', () => {
165	  const b = fleetBenefits([
166	    read({ repo: 'o/fresh', declaration: { claudinite: { updated: '2026-08-18T02:00:00Z' } } }),
167	    read({ repo: 'o/stopped', declaration: { claudinite: { updated: '2026-06-01T02:00:00Z' } } }),
168	  ], { now: NOW, windowDays: 7 });
169	  assert.equal(b.converged, 1);
170	  assert.equal(b.members, 2);
171	});
172	
173	test('digests are counted from what was actually found, and null when none was looked for', () => {
174	  const withDigests = fleetBenefits([read()], { now: NOW, digests: [{ text: 'a' }, { text: null }] });
175	  assert.equal(withDigests.digests, 1);
176	  assert.equal(fleetBenefits([read()], { now: NOW }).digests, null);
177	});

1	// What the fleet DID — the counterpart to every other derivation here, which answers
2	// where to look. Pure: no clock, no I/O, no DOM.
3	//
4	// The page's panels are all fault-finding, and fault-finding has a blind spot: after
5	// a good week every count is zero, so a healthy fleet and a dead one render
6	// identically. Nothing on the page can tell them apart, because "nothing is wrong" and
7	// "nothing happened" are the same picture. This module is the other reading — closed
8	// work, scheduler runs, and which members moved at all — over a window of days.
9	//
10	// EVERY NUMBER COMES FROM A READ THE PAGE ALREADY MAKES. A per-member call to get a
11	// commit count would undo the budget work the whole client is built around, so the
12	// inputs are exactly the fleet loader's existing per-member reads: the first page of
13	// issues, the recent Actions runs, and the head commit whose date arrives with the sha
14	// the content cache is keyed by. Nothing here adds a request.
15	//
16	// WHAT THAT COSTS IS DEPTH, AND DEPTH IS DECLARED. One issue page is the most recent
17	// hundred issues by creation, and one runs page is the most recent thirty runs — so a
18	// day at the far end of the window is under-read rather than empty, and every series
19	// carries the horizon past which it stops being a count and starts being a floor.
20	
21	import {
22	  NEEDS_HUMAN, OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE,
23	} from '../../engine/scheduler/queue/work-item.mjs';
24	import { isWorkItem } from './model.mjs';
25	
26	export const DAY_MS = 86400e3;
27	
28	const ms = (t) => (t == null ? null : new Date(t).getTime());
29	
30	// A UTC day. The queue's anchors, the digests' file names and GitHub's timestamps are
31	// all UTC, so a local-time bucketing would put a member's midnight run on the wrong
32	// day depending on who is looking.
33	export const dayKey = (t) => new Date(t).toISOString().slice(0, 10);
34	
35	// The window's days, oldest first, including today. Built from keys rather than from
36	// arithmetic on a rendered date so a DST-free UTC ladder is the only thing anyone has
37	// to trust.
38	export function dayLadder(now, days) {
39	  const start = Math.floor(now / DAY_MS) * DAY_MS - (days - 1) * DAY_MS;
40	  return Array.from({ length: days }, (_, i) => dayKey(start + i * DAY_MS));
41	}
42	
43	const outcomeOfLabels = (labels = []) =>
44	  [OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE].find((o) => labels.includes(o)) ?? null;
45	
46	// --- the daily series -----------------------------------------------------------
47	
48	// Work closed, runs finished and members moving, per day. `reads` is the fleet
49	// loader's raw per-member reads; a member that could not be read contributes nothing
50	// and is counted as unread rather than as a quiet day.
51	export function activitySeries(reads, { now, days = 14 } = {}) {
52	  const ladder = dayLadder(now, days);
53	  const index = new Map(ladder.map((d, i) => [d, i]));
54	  const blank = () => ladder.map((day) => ({
55	    day,
56	    work: { [OUTCOME_DONE]: 0, [OUTCOME_DELIVERED]: 0, [OUTCOME_OBSOLETE]: 0, none: 0 },
57	    workClosed: 0,
58	    otherClosed: 0,
59	    runs: { success: 0, failure: 0, other: 0 },
60	    movers: new Set(),
61	  }));
62	
63	  const series = blank();
64	  const readable = (reads ?? []).filter((r) => r && !r.error && r.declaration);
65	  // The oldest thing each read could see. A day before this is under-read for that
66	  // member — not quiet — and the series says so rather than drawing a confident zero.
67	  let issueHorizon = null;
68	  let runHorizon = null;
69	  const seen = (at, keep) => {
70	    const t = ms(at);
71	    if (t == null) return keep;
72	    return keep == null ? t : Math.max(keep, t);
73	  };
74	
75	  for (const read of readable) {
76	    const items = read.items ?? [];
77	    let oldestIssue = null;
78	    for (const i of items) {
79	      const created = ms(i.created_at);
80	      if (created != null) oldestIssue = oldestIssue == null ? created : Math.min(oldestIssue, created);
81	      if (i.state !== 'closed') continue;
82	      const at = ms(i.closed_at) ?? ms(i.updated_at);
83	      const slot = at == null ? undefined : index.get(dayKey(at));
84	      if (slot === undefined) continue;
85	      series[slot].movers.add(read.repo);
86	      if (isWorkItem(i)) {
87	        series[slot].workClosed += 1;
88	        series[slot].work[outcomeOfLabels(i.labels) ?? 'none'] += 1;
89	      } else {
90	        series[slot].otherClosed += 1;
91	      }
92	    }
93	    // A member whose page-1 window does not reach the start of the ladder truncates
94	    // the series for everyone, so the horizon is the LATEST such floor across members.
95	    if (!read.itemsComplete && oldestIssue != null) issueHorizon = seen(oldestIssue, issueHorizon);
96	
97	    let oldestRun = null;
98	    for (const r of read.runs ?? []) {
99	      const at = ms(r.created_at);
100	      if (at == null) continue;
101	      oldestRun = oldestRun == null ? at : Math.min(oldestRun, at);
102	      const slot = index.get(dayKey(at));
103	      if (slot === undefined) continue;
104	      series[slot].movers.add(read.repo);
105	      const bucket = r.status !== 'completed' ? 'other'
106	        : r.conclusion === 'success' ? 'success'
107	          : (r.conclusion === 'failure' || r.conclusion === 'timed_out' || r.conclusion === 'startup_failure') ? 'failure'
108	            : 'other';
109	      series[slot].runs[bucket] += 1;
110	    }
111	    if (oldestRun != null) runHorizon = seen(oldestRun, runHorizon);
112	
113	    // The default branch's tip. One date, so it marks the day that member last
114	    // landed something — not a commit count, and never drawn as one.
115	    const tip = ms(read.head?.committedAt);
116	    const tipSlot = tip == null ? undefined : index.get(dayKey(tip));
117	    if (tipSlot !== undefined) series[tipSlot].movers.add(read.repo);
118	  }
119	
120	  const rows = series.map((d) => ({ ...d, movers: [...d.movers].sort(), moved: d.movers.size }));
121	  const movedInWindow = new Set(rows.flatMap((d) => d.movers));
122	
123	  return {
124	    days: rows,
125	    from: ladder[0],
126	    to: ladder[ladder.length - 1],
127	    members: readable.length,
128	    unread: (reads ?? []).filter((r) => r?.error).length,
129	    moved: [...movedInWindow].sort(),
130	    quiet: readable.map((r) => r.repo).filter((r) => !movedInWindow.has(r)).sort(),
131	    totals: {
