1	// The fleet's morning brief, as the dashboard reads it. Pure: no clock, no I/O, no DOM.
2	//
3	// This pack's own `fleet-digest` task writes one file per day at `digests/<date>.md`
4	// in the fleet enforcer's repo — the few things the fleet actually accomplished, and the
5	// project worth returning to. Nothing surfaced it until now, and the dashboard is
6	// where someone is already looking.
7	//
8	// IT IS PLAIN TEXT, NOT MARKDOWN, despite the `.md` name. That is the task's own
9	// contract and a check enforces it over the landed series: the brief is read out
10	// verbatim through a renderer that parses no markdown and keeps no line breaks, so it
11	// carries no headings, no bullet syntax, no bold and no link syntax — a `• ` opens
12	// each item and every URL sits bare. So the right reader here is NOT a Markdown
13	// library: it is a few rules over lines, which is also the smallest honest thing the
14	// page can do with a file whose shape is fixed.
15	//
16	// The forgiving half — a `#` heading or a `- ` bullet is accepted anyway — costs three
17	// lines and means a hand-written or older brief still renders as prose rather than as
18	// a wall with stray punctuation.
19	
20	const DAY_MS = 86400e3;
21	
22	// Which days to show: yesterday and the day before. Today is deliberately not among
23	// them — the brief for a day is written after that day, so today's file does not exist
24	// yet and asking for it would spend a request to learn nothing.
25	export function digestDates(now, count = 2) {
26	  const midnight = Math.floor(now / DAY_MS) * DAY_MS;
27	  return Array.from({ length: count }, (_, i) => new Date(midnight - (i + 1) * DAY_MS).toISOString().slice(0, 10));
28	}
29	
30	export const digestPath = (dir, date) => `${String(dir ?? 'digests').replace(/^\/|\/$/g, '')}/${date}.md`;
31	
32	const URL_RE = /https?:\/\/[^\s<>()]+[^\s<>().,;:]/g;
33	
34	// A line, split into the text and link runs a renderer can build nodes from. Bare URLs
35	// are the brief's only link form, because that is the only one its writer is allowed.
36	export function linkRuns(line) {
37	  const out = [];
38	  let at = 0;
39	  for (const m of String(line).matchAll(URL_RE)) {
40	    if (m.index > at) out.push({ text: line.slice(at, m.index) });
41	    out.push({ text: m[0], href: m[0] });
42	    at = m.index + m[0].length;
43	  }
44	  if (at < line.length) out.push({ text: line.slice(at) });
45	  return out;
46	}
47	
48	// The brief as blocks. Four kinds, which is all its shape has:
49	//
50	//   title    the first line, naming the fleet and the day
51	//   section  a line that ends in a colon — "Yesterday's biggest work:"
52	//   item     a bulleted accomplishment
53	//   para     anything else, which is the nudge's closing sentence
54	export function parseDigest(text) {
55	  const lines = String(text ?? '').split(/\r?\n/);
56	  const blocks = [];
57	  let seenTitle = false;
58	
59	  for (const raw of lines) {
60	    const line = raw.trim();
61	    if (!line) continue;
62	
63	    const bullet = /^([•*-]|\d+\.)\s+/.exec(line);
64	    if (bullet) {
65	      blocks.push({ kind: 'item', runs: linkRuns(line.slice(bullet[0].length)) });
66	      continue;
67	    }
68	
69	    const heading = /^#{1,6}\s+/.exec(line);
70	    const body = heading ? line.slice(heading[0].length) : line;
71	
72	    if (!seenTitle) {
73	      seenTitle = true;
74	      blocks.push({ kind: 'title', runs: linkRuns(body) });
75	      continue;
76	    }
77	    if (heading || /:$/.test(body)) {
78	      blocks.push({ kind: 'section', runs: linkRuns(body.replace(/:$/, '')) });
79	      continue;
80	    }
81	    blocks.push({ kind: 'para', runs: linkRuns(body) });
82	  }
83	  return blocks;
84	}
85	
86	// What the page knows about one day's brief. A missing file is a NORMAL state — the
87	// task had nothing to report, or has not run yet — and it is carried as `missing`
88	// with no error attached, because a day without a brief is not a fault to report.
89	export function digestEntry(date, text, error = null) {
90	  if (error) return { date, text: null, state: 'unreadable', error, blocks: [] };
91	  if (text == null) return { date, text: null, state: 'missing', error: null, blocks: [] };
92	  const blocks = parseDigest(text);
93	  return { date, text, state: blocks.length ? 'written' : 'empty', error: null, blocks };
94	}

